          "type": "string"
        },
        "target_block_ref": {
          "title": "Target Block Ref",
          "type": "string"
        },
        "condition_text": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Condition Text"
        }
      },
      "required": [
        "source_block_ref",
        "target_block_ref"
      ],
      "title": "CandidateEdge",
      "type": "object"
    },
    "CandidateInstruction": {
      "additionalProperties": false,
      "description": "An instruction proposed by the LLM before canonical compilation.",
      "properties": {
