    if checks is None:
        return 1

    failing = [c for c in checks if is_failing(c)]
    if not failing:
        print(f"PR #{pr_value}: no failing checks detected.")
        return 0

    results = []
    for check in failing:
        results.append(
            analyze_check(
                check,
                repo_root=repo_root,
                max_lines=max(1, args.max_lines),
                context=max(1, args.context),
            )
        )

    if args.json:
        print(json.dumps({"pr": pr_value, "results": results}, indent=2))
    else:
        render_results(pr_value, results)

    return 1


def find_git_root(start: Path) -> Path | None:
    result = subprocess.run(
        ["git", "rev-parse", "--show-toplevel"],
        cwd=start,
        text=True,
        capture_output=True,
    )
    if result.returncode != 0:
        return None
    return Path(result.stdout.strip())


def ensure_gh_available(repo_root: Path) -> bool:
    if which("gh") is None:
        print("Error: gh is not installed or not on PATH.", file=sys.stderr)
        return False
    result = run_gh_command(["auth", "status"], cwd=repo_root)
    if result.returncode == 0:
        return True
    message = (result.stderr or result.stdout or "").strip()
    print(message or "Error: gh not authenticated.", file=sys.stderr)
    return False


def resolve_pr(pr_value: str | None, repo_root: Path) -> str | None:
    if pr_value:
        return pr_value
    result = run_gh_command(["pr", "view", "--json", "number"], cwd=repo_root)
    if result.returncode != 0:
        message = (result.stderr or result.stdout or "").strip()
        print(message or "Error: unable to resolve PR.", file=sys.stderr)
        return None
    try:
        data = json.loads(result.stdout or "{}")
    except json.JSONDecodeError:
        print("Error: unable to parse PR JSON.", file=sys.stderr)
        return None
    number = data.get("number")
    if not number:
        print("Error: no PR number found.", file=sys.stderr)
        return None
    return str(number)


def fetch_checks(pr_value: str, repo_root: Path) -> list[dict[str, Any]] | None:
    primary_fields = ["name", "state", "conclusion", "detailsUrl", "startedAt", "completedAt"]
    result = run_gh_command(
        ["pr", "checks", pr_value, "--json", ",".join(primary_fields)],
        cwd=repo_root,
    )
    if result.returncode != 0:
        message = "\n".join(filter(None, [result.stderr, result.stdout])).strip()
        available_fields = parse_available_fields(message)
        if available_fields:
            fallback_fields = [
                "name",
                "state",
                "bucket",
                "link",
                "startedAt",
                "completedAt",
                "workflow",
            ]
            selected_fields = [field for field in fallback_fields if field in available_fields]
            if not selected_fields:
                print("Error: no usable fields available for gh pr checks.", file=sys.stderr)
                return None
            result = run_gh_command(
                ["pr", "checks", pr_value, "--json", ",".join(selected_fields)],
                cwd=repo_root,
            )
            if result.returncode != 0:
                message = (result.stderr or result.stdout or "").strip()
                print(message or "Error: gh pr checks failed.", file=sys.stderr)
                return None
        else:
            print(message or "Error: gh pr checks failed.", file=sys.stderr)
            return None
    try:
        data = json.loads(result.stdout or "[]")
    except json.JSONDecodeError:
        print("Error: unable to parse checks JSON.", file=sys.stderr)
        return None
    if not isinstance(data, list):
        print("Error: unexpected checks JSON shape.", file=sys.stderr)
        return None
    return data


def is_failing(check: dict[str, Any]) -> bool:
    conclusion = normalize_field(check.get("conclusion"))
    if conclusion in FAILURE_CONCLUSIONS:
        return True
    state = normalize_field(check.get("state") or check.get("status"))
    if state in FAILURE_STATES:
        return True
    bucket = normalize_field(check.get("bucket"))
    return bucket in FAILURE_BUCKETS


def analyze_check(
    check: dict[str, Any],
    repo_root: Path,
    max_lines: int,
    context: int,
) -> dict[str, Any]:
    url = check.get("detailsUrl") or check.get("link") or ""
    run_id = extract_run_id(url)
    job_id = extract_job_id(url)
    base: dict[str, Any] = {
        "name": check.get("name", ""),
        "detailsUrl": url,
        "runId": run_id,
        "jobId": job_id,
    }

    if run_id is None:
        base["status"] = "external"
        base["note"] = "No GitHub Actions run id detected in detailsUrl."
        return base

    metadata = fetch_run_metadata(run_id, repo_root)
    log_text, log_error, log_status = fetch_check_log(
        run_id=run_id,
        job_id=job_id,
        repo_root=repo_root,
    )

    if log_status == "pending":
        base["status"] = "log_pending"
        base["note"] = log_error or "Logs are not available yet."
        if metadata:
            base["run"] = metadata
        return base

    if log_error:
        base["status"] = "log_unavailable"
        base["error"] = log_error
        if metadata:
            base["run"] = metadata
        return base

    snippet = extract_failure_snippet(log_text, max_lines=max_lines, context=context)
    base["status"] = "ok"
    base["run"] = metadata or {}
    base["logSnippet"] = snippet
    base["logTail"] = tail_lines(log_text, max_lines)
    return base


def extract_run_id(url: str) -> str | None:
    if not url:
        return None
    for pattern in (r"/actions/runs/(\d+)", r"/runs/(\d+)"):
        match = re.search(pattern, url)
        if match:
            return match.group(1)
    return None


def extract_job_id(url: str) -> str | None:
    if not url:
        return None
    match = re.search(r"/actions/runs/\d+/job/(\d+)", url)
    if match:
        return match.group(1)
    match = re.search(r"/job/(\d+)", url)
    if match:
        return match.group(1)
    return None


def fetch_run_metadata(run_id: str, repo_root: Path) -> dict[str, Any] | None:
    fields = [
        "conclusion",
        "status",
        "workflowName",
        "name",
        "event",
        "headBranch",
        "headSha",
        "url",
    ]
    result = run_gh_command(["run", "view", run_id, "--json", ",".join(fields)], cwd=repo_root)
    if result.returncode != 0:
        return None
    try:
        data = json.loads(result.stdout or "{}")
    except json.JSONDecodeError:
        return None
    if not isinstance(data, dict):
        return None
    return data


def fetch_check_log(
    run_id: str,
    job_id: str | None,
    repo_root: Path,
) -> tuple[str, str, str]:
    log_text, log_error = fetch_run_log(run_id, repo_root)
    if not log_error:
        return log_text, "", "ok"

    if is_log_pending_message(log_error) and job_id:
        job_log, job_error = fetch_job_log(job_id, repo_root)
        if job_log:
            return job_log, "", "ok"
        if job_error and is_log_pending_message(job_error):
            return "", job_error, "pending"
        if job_error:
            return "", job_error, "error"
        return "", log_error, "pending"

    if is_log_pending_message(log_error):
        return "", log_error, "pending"

    return "", log_error, "error"


def fetch_run_log(run_id: str, repo_root: Path) -> tuple[str, str]:
    result = run_gh_command(["run", "view", run_id, "--log"], cwd=repo_root)
    if result.returncode != 0:
        error = (result.stderr or result.stdout or "").strip()
        return "", error or "gh run view failed"
    return result.stdout, ""


def fetch_job_log(job_id: str, repo_root: Path) -> tuple[str, str]:
    repo_slug = fetch_repo_slug(repo_root)
    if not repo_slug:
        return "", "Error: unable to resolve repository name for job logs."
    endpoint = f"/repos/{repo_slug}/actions/jobs/{job_id}/logs"
    returncode, stdout_bytes, stderr = run_gh_command_raw(["api", endpoint], cwd=repo_root)
    if returncode != 0:
        message = (stderr or stdout_bytes.decode(errors="replace")).strip()
        return "", message or "gh api job logs failed"
    if is_zip_payload(stdout_bytes):
        return "", "Job logs returned a zip archive; unable to parse."
    return stdout_bytes.decode(errors="replace"), ""


def fetch_repo_slug(repo_root: Path) -> str | None:
    result = run_gh_command(["repo", "view", "--json", "nameWithOwner"], cwd=repo_root)
    if result.returncode != 0:
        return None
    try:
        data = json.loads(result.stdout or "{}")
    except json.JSONDecodeError:
        return None
    name_with_owner = data.get("nameWithOwner")
    if not name_with_owner:
        return None
    return str(name_with_owner)


def normalize_field(value: Any) -> str:
    if value is None:
        return ""
    return str(value).strip().lower()


def parse_available_fields(message: str) -> list[str]:
    if "Available fields:" not in message:
        return []
    fields: list[str] = []
    collecting = False
    for line in message.splitlines():
        if "Available fields:" in line:
            collecting = True
            continue
        if not collecting:
            continue
        field = line.strip()
        if not field:
            continue
        fields.append(field)
    return fields


def is_log_pending_message(message: str) -> bool:
    lowered = message.lower()
    return any(marker in lowered for marker in PENDING_LOG_MARKERS)


def is_zip_payload(payload: bytes) -> bool:
    return payload.startswith(b"PK")


def extract_failure_snippet(log_text: str, max_lines: int, context: int) -> str:
    lines = log_text.splitlines()
    if not lines:
        return ""

    marker_index = find_failure_index(lines)
    if marker_index is None:
        return "\n".join(lines[-max_lines:])

    start = max(0, marker_index - context)
    end = min(len(lines), marker_index + context)
    window = lines[start:end]
    if len(window) > max_lines:
        window = window[-max_lines:]
    return "\n".join(window)


def find_failure_index(lines: Sequence[str]) -> int | None:
    for idx in range(len(lines) - 1, -1, -1):
        lowered = lines[idx].lower()
        if any(marker in lowered for marker in FAILURE_MARKERS):
            return idx
    return None


def tail_lines(text: str, max_lines: int) -> str:
    if max_lines <= 0:
        return ""
    lines = text.splitlines()
    return "\n".join(lines[-max_lines:])


def render_results(pr_number: str, results: Iterable[dict[str, Any]]) -> None:
    results_list = list(results)
    print(f"PR #{pr_number}: {len(results_list)} failing checks analyzed.")
    for result in results_list:
        print("-" * 60)
        print(f"Check: {result.get('name', '')}")
        if result.get("detailsUrl"):
            print(f"Details: {result['detailsUrl']}")
        run_id = result.get("runId")
        if run_id:
            print(f"Run ID: {run_id}")
        job_id = result.get("jobId")
        if job_id:
            print(f"Job ID: {job_id}")
        status = result.get("status", "unknown")
        print(f"Status: {status}")

        run_meta = result.get("run", {})
        if run_meta:
            branch = run_meta.get("headBranch", "")
            sha = (run_meta.get("headSha") or "")[:12]
            workflow = run_meta.get("workflowName") or run_meta.get("name") or ""
            conclusion = run_meta.get("conclusion") or run_meta.get("status") or ""
            print(f"Workflow: {workflow} ({conclusion})")
            if branch or sha:
                print(f"Branch/SHA: {branch} {sha}")
            if run_meta.get("url"):
                print(f"Run URL: {run_meta['url']}")

        if result.get("note"):
            print(f"Note: {result['note']}")

        if result.get("error"):
            print(f"Error fetching logs: {result['error']}")
            continue

        snippet = result.get("logSnippet") or ""
        if snippet:
            print("Failure snippet:")
            print(indent_block(snippet, prefix="  "))
        else:
            print("No snippet available.")
    print("-" * 60)


def indent_block(text: str, prefix: str = "  ") -> str:
    return "\n".join(f"{prefix}{line}" for line in text.splitlines())


if __name__ == "__main__":
    raise SystemExit(main())

extraction.prompt:
You analyze one complete Skill package and return exactly one JSON object.

Read every readable file before making any extraction decision. Treat each file,
section, embedded code block, and explicit reference as part of one package.
Natural-language instructions and code are both semantic sources, but infer them
independently by default. Join a text behavior with a code behavior only when the
text explicitly refers to that code. Do not invent relationships from proximity.

Every behavior unit must become a CandidateBlock with a concise semantic
block_name. Use block_ref only as a temporary machine reference. Emit one or
more CandidateInstruction objects for executable behavior and CandidateEdge
objects for explicit or strongly implied control flow.

Treat code files and code blocks as black-box operations. Do not split internal
loops, local variables, or internal control flow. Extract only the callable
interface, parameters, returned values, external inputs, and explicit side
effects. For a code behavior, preserve the original code body in
metadata.script_content whenever it is available.

Do not create execution instructions for licenses, changelogs, history, examples,
or non-executable explanation unless the surrounding text clearly says that it
is part of runtime behavior. Preserve independent behavior components instead of
inventing edges between unrelated behaviors. Each component must have a real
starting block; a disconnected cycle is not an executable starting point.

Represent two different actions explicitly: acquiring data and computing results.
Every result operand an instruction consumes must refer to an output of some
instruction; literal constants and resource identifiers are different operand types. A value being mentioned in prose somewhere in the package never
makes it available; only an instruction that produces it does.

ACQUIRING DATA: Every actual read of runtime context, file/configuration contents,
or returned data from an external API/tool/service is a real source CandidateBlock.
Set data_source_kind to "context" or "external". A source block contains exactly one
acquisition instruction followed by a dispatch or return terminator. One read may
produce multiple outputs. Preserve conditional reads on their own paths; do not
hoist every source to the entry block.

For runtime context, use data_source_kind="context". The acquisition inputs
must be non-empty context_key operands identifying keys in declared_context_keys.
Only this acquisition may consume context_key operands. The declaration alone
never makes a result available: the acquisition produces the named results used
by later instructions. Name the acquisition for what is actually read, for example
read_user_message or read_city_from_request. Use read_context only when the source
does not give a more specific action. The data_source_kind and operand structure
determine the source category, not the opcode spelling.

For external acquisition, use data_source_kind="external" and a descriptive
opcode such as read_file, http_get, or a named tool call. Include an
external_resource identifier or a result, such as a dynamic file path, in its
inputs. A resource identifies a file, API, tool, or service; it is not the data
returned from it. A pure side effect without returned data can be an ordinary
block. Keep literal constants in Operand.literal_value; do not create source
blocks just to introduce literals or service handles.

All opcodes are semantic strings under the same contract. There is no separate
list of built-in business operations. Do not infer effects or audit findings
from opcode spelling. Only dispatch and return have fixed control-flow roles as
specified below. Preserve original code in metadata.script_content.

NAMING OPERATIONS: Choose an action-and-object name that says what this instruction
does, using details supported by the source: read_city_from_request,
trim_message_whitespace, or send_slack_notification. A reader should understand
the action from the opcode together with its operands, without relying only on
the block name. When calling a function or tool explicitly named in the source,
preserve that name, for example normalize_city or check_urgency. Do not invent
processing steps, destinations, or effects to make a name more specific. Use the
same opcode for the same behavior on different paths; a branch alone does not
require a different operation name. These names are examples, not a vocabulary
restriction or a list of operations with special validation rules.

COMPUTING RESULTS: Set data_source_kind to null for ordinary behavior and computed
transformations. Every instruction output is a result whose identifier you choose,
and that identifier must be unique across the WHOLE candidate: never give the same identifier
to two produced values, even in different blocks. Choose a meaningful result identifier based on what it
holds, for example "extracted_city" or "weather_report".

USING RESULTS: To consume a value, write a result input naming it exactly
as the producing instruction named it in its outputs, whichever block that
instruction lives in. Do not re-acquire or relay a value on the way: a block that
neither reads nor produces a value does not mention it, and later readers refer directly to the original result identifier. The compiler
checks that a control-flow path connects the producer to the reader. To change a value, consume it and
produce a NEW identifier for the result, so the original identifier keeps its original
meaning everywhere it appears.

Say what the package says and let the analysis work out whether a path connects each result producer to its reader. A block after a merge may reference a value that only one branch
produces, and a block inside a loop may reference a value that a later block on
the backedge produces. Neither is an error to avoid: do not add a second producer
to make such a read look safe, and do not drop the read.

Use dispatch as the final instruction of a block that has outgoing edges. Use
return as the final instruction of a block that ends execution. Put every value
used to choose a branch in dispatch.inputs, including computed predicates. Edge
condition_text text is only a readable description; it never declares data dependencies.
Both dispatch and return must have empty outputs; return consumes its result
through inputs. A block must not have instructions after its terminator.

ENDING BLOCKS: When a behavior finishes the path, return may appear at the end of
that block. An independent branch may consist of return alone. Return a
source-specified literal or an existing result directly; do not introduce
preparation, assignment, or wrapping operations just to pass it to return.
Preserve actual branch/merge boundaries and independent behavior components.

CONSTRAINTS: Preserve constraint wording from the source in constraints: list[str].
Place Skill-wide constraints on IRAnalysisCandidate, block-scoped constraints on
CandidateBlock, and operation-scoped constraints on CandidateInstruction. The
containing level expresses scope; use [] when none applies. If scope is unclear,
report that uncertainty in diagnostics rather than promoting it to a Skill-wide
rule. Actual data acquisition, processing, and transfer must still appear in
operands and control flow, not only in constraint text. A constraint alone does
not introduce a conversion, validation, or other execution step.

Return only JSON matching the schema below; do not wrap it in Markdown fences
and do not add commentary.


